package com.badrulamin.University_Management.service; import com.badrulamin.University_Management.exception.ResourceNotFoundException;  import com.badrulamin.University_Management.entity.AdmissionOfferLetter; import com.badrulamin.University_Management.repository.AdmissionOfferLetterRepository; import org.springframework.data.domain.Page; import org.springframework.data.domain.Pageable; import org.springframework.stereotype.Service;  import java.time.LocalDateTime; import java.util.UUID;  @Service public class AdmissionOfferLetterService {      private final AdmissionOfferLetterRepository admissionOfferLetterRepository;      public AdmissionOfferLetterService(AdmissionOfferLetterRepository admissionOfferLetterRepository) {         this.admissionOfferLetterRepository = admissionOfferLetterRepository;     }      public Page<AdmissionOfferLetter> findAll(Pageable pageable) {         return admissionOfferLetterRepository.findAll(pageable);     }      public AdmissionOfferLetter findById(Long id) {         return admissionOfferLetterRepository.findById(id).orElseThrow(() -> new ResourceNotFoundException("AdmissionOfferLetter", "id", id));     }      public AdmissionOfferLetter create(AdmissionOfferLetter offerLetter) {         offerLetter.setLetterNumber("OL-" + UUID.randomUUID().toString().substring(0, 8).toUpperCase());         offerLetter.setIssuedAt(LocalDateTime.now());         offerLetter.setIsDownloaded(false);         offerLetter.setStatus("ISSUED");         return admissionOfferLetterRepository.save(offerLetter);     }      public AdmissionOfferLetter update(Long id, AdmissionOfferLetter offerLetter) {         AdmissionOfferLetter existing = admissionOfferLetterRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AdmissionOfferLetter", "id", id));         existing.setApplication(offerLetter.getApplication());         existing.setMeritListEntry(offerLetter.getMeritListEntry());         existing.setValidUntil(offerLetter.getValidUntil());         existing.setStatus(offerLetter.getStatus());         existing.setLetterContent(offerLetter.getLetterContent());         existing.setConditions(offerLetter.getConditions());         existing.setRemarks(offerLetter.getRemarks());         existing.setIssuedBy(offerLetter.getIssuedBy());         return admissionOfferLetterRepository.save(existing);     }      public void delete(Long id) {         admissionOfferLetterRepository.deleteById(id);     }      public AdmissionOfferLetter accept(Long id) {         AdmissionOfferLetter existing = admissionOfferLetterRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AdmissionOfferLetter", "id", id));         existing.setStatus("ACCEPTED");         existing.setAcceptedAt(LocalDateTime.now());         return admissionOfferLetterRepository.save(existing);     }      public AdmissionOfferLetter decline(Long id, String reason) {         AdmissionOfferLetter existing = admissionOfferLetterRepository.findById(id)                 .orElseThrow(() -> new ResourceNotFoundException("AdmissionOfferLetter", "id", id));         existing.setStatus("DECLINED");         existing.setDeclinedAt(LocalDateTime.now());         existing.setDeclineReason(reason);         return admissionOfferLetterRepository.save(existing);     }      public long countByStatus(String status) {         return admissionOfferLetterRepository.countByStatus(status);     } }